    public void appandToRankList(int flag) {
        List<JEngineNetPkEntry> items = null;
        LinearLayout listview = null;
        if (flag == 0) {
            items = JEngineNetPkEntryManager.getInstance().getUserRankList();
            listview = this.mJNetPkListViewUser;
        } else if (flag == 1) {
            items = JEngineNetPkEntryManager.getInstance().getTopRankList();
            listview = this.mJNetPkListViewTop;
        } else if (flag == 2) {
            items = JEngineNetPkEntryManager.getInstance().getArenaRankList();
            listview = this.mJNetPkListViewArena;
        }
        listview.removeAllViews();
        listview.setOrientation(1);
        byte[] param = new byte[256];
        GetNetPkUidAndPsw(param);
        String p = new String(param);
        String uid = p.split("&")[0];
        if (items != null) {
            View[] view = new View[items.size()];
            for (int i = 0; i < items.size(); i++) {
                if (flag == 0) {
                    view[i] = View.inflate(this.mJNetPkActivity, R.layout.jt_listview_item_nonchess, null);
                    view[i].setId(i);
                } else if (flag == 1) {
                    view[i] = View.inflate(this.mJNetPkActivity, R.layout.jt_listview_item_top_nonchess, null);
                    view[i].setId(i);
                } else if (flag == 2) {
                    view[i] = View.inflate(this.mJNetPkActivity, R.layout.jt_listview_item_top_nonchess, null);
                    view[i].setId(i);
                }
                TextView rank = (TextView) view[i].findViewById(R.id.jt_txtRankNum);
                rank.setText(items.get(i).mRank);
                TextView nick = (TextView) view[i].findViewById(R.id.jt_txtNickname);
                TextView level = (TextView) view[i].findViewById(R.id.jt_txtLevel);
                ImageView show = (ImageView) view[i].findViewById(R.id.jt_imgShow);
                if (flag == 2 && (items.get(i).mUserId.equals(HttpNet.URL) || items.get(i).mUserId.equals("0"))) {
                    nick.setText(this.mJNetPkActivity.getString(R.string.jt_arena_none));
                    level.setText("----");
                    show.setImageResource(R.drawable.unknow);
                } else {
                    if (items.get(i).mNick.equals(HttpNet.URL)) {
                        nick.setText(this.mJNetPkActivity.getString(R.string.jt_nickname_none));
                    } else {
                        nick.setText(items.get(i).mNick);
                    }
                    if (items.get(i).mLevel == null || items.get(i).mLevel.equals(HttpNet.URL)) {
                        level.setText("lv.1");
                    } else {
                        level.setText(items.get(i).mLevel);
                    }
                    if (items.get(i).mShow == null || items.get(i).mShow.equals(HttpNet.URL)) {
                        show.setImageResource(R.drawable.unknow);
                    } else {
                        show.setImageResource(getDrawableId("jt_rank_show" + (Integer.parseInt(items.get(i).mShow) + 1)));
                    }
                }
                TextView score = (TextView) view[i].findViewById(R.id.jt_txtBests);
                score.setText(items.get(i).mScore);
                if (flag == 1 || flag == 2) {
                    ImageView star1 = (ImageView) view[i].findViewById(R.id.jt_topImgCupDuplication);
                    ImageView star2 = (ImageView) view[i].findViewById(R.id.jt_topImgCup);
                    if (items.get(i).mRank.equals(NETPK_SERVER_ACTION_REGISTER)) {
                        star1.setBackgroundResource(R.drawable.jt_cup_first);
                        star2.setBackgroundResource(R.drawable.jt_cup_first);
                        rank.setBackgroundResource(R.drawable.jt_rank_bg_first);
                    } else if (items.get(i).mRank.equals(NETPK_SERVER_ACTION_MODIFY)) {
                        star1.setBackgroundResource(R.drawable.jt_cup_second);
                        star2.setBackgroundResource(R.drawable.jt_cup_second);
                        rank.setBackgroundResource(R.drawable.jt_rank_bg_second);
                    } else if (items.get(i).mRank.equals(NETPK_SERVER_ACTION_UPLOAD)) {
                        star1.setBackgroundResource(R.drawable.jt_cup_third);
                        star2.setBackgroundResource(R.drawable.jt_cup_third);
                        rank.setBackgroundResource(R.drawable.jt_rank_bg_third);
                    }
                }
                if (items.get(i).mUserId.equals(uid) && (flag == 0 || flag == 2)) {
                    view[i].setBackgroundResource(R.drawable.jt_rank_list_item_selected);
                    this.mJNetPkUserScorllViewH = i;
                }
                listview.addView(view[i]);
            }
            if ((flag == 0 || flag == 2) && this.mJNetPkScrollViewUser != null) {
                Handler handler = new Handler();
                handler.postDelayed(this.runnable, 25L);
            }
        }
    }

