    public void parseRankData(String data, int flag) {
        String[] ret = data.split("▨");
        int start = Integer.parseInt(ret[1]);
        String[] entry = ret[2].split("▧");
        for (int i = 0; i < entry.length; i++) {
            String[] items = entry[i].split("▤");
            if ((items.length >= 2 && items[0].length() > 0) || flag == 2) {
                List<String> params = null;
                String lv = HttpNet.URL;
                String show = HttpNet.URL;
                String uid = HttpNet.URL;
                String score = "0";
                String nick = HttpNet.URL;
                if (items.length > 5) {
                    params = new ArrayList<>();
                    for (int j = 5; j < items.length; j++) {
                        params.add(items[j]);
                    }
                }
                if (items.length >= 1) {
                    uid = items[0];
                }
                if (items.length >= 2) {
                    score = items[1];
                }
                if (items.length >= 3) {
                    nick = items[2];
                }
                if (items.length >= 4) {
                    lv = items[3];
                }
                if (lv.equals(HttpNet.URL) || lv.equals("0")) {
                    lv = NETPK_SERVER_ACTION_REGISTER;
                }
                if (items.length >= 5) {
                    show = items[4];
                }
                if (flag == 0) {
                    JEngineNetPkEntryManager.getInstance().addUserRank(uid, new StringBuilder().append(start + i).toString(), score, "lv." + lv, show, nick, params);
                } else if (flag == 1) {
                    JEngineNetPkEntryManager.getInstance().addTopRank(uid, new StringBuilder().append(start + i).toString(), score, "lv." + lv, show, nick, params);
                } else if (flag == 2) {
                    JEngineNetPkEntryManager.getInstance().addArenaRank(uid, new StringBuilder().append(start + i).toString(), score, "lv." + lv, show, nick, params);
                }
            }
        }
    }

